import{_ as e,c as r,o as n,a2 as a}from"./chunks/framework.CIiVzG-O.js";const x=JSON.parse('{"title":"支持的格式","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/formats.md","filePath":"zh-CN/guide/formats.md","lastUpdated":1793163976000}'),l={name:"zh-CN/guide/formats.md"};function d(s,t,i,o,g,c){return n(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="支持的格式" tabindex="-1">支持的格式 <a class="header-anchor" href="#支持的格式" aria-label="Permalink to &quot;支持的格式&quot;">​</a></h1><p>NueZip 支持广泛范围的归档格式，既能读取也能写入。以下是完整的格式兼容性矩阵。</p><h2 id="格式矩阵" tabindex="-1">格式矩阵 <a class="header-anchor" href="#格式矩阵" aria-label="Permalink to &quot;格式矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格式</th><th style="text-align:center;">读取</th><th style="text-align:center;">写入（压缩）</th><th style="text-align:center;">加密</th><th style="text-align:center;">多卷</th></tr></thead><tbody><tr><td><strong>ZIP</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">AES-256</td><td style="text-align:center;">✅</td></tr><tr><td><strong>7-Zip (.7z)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">AES-256 (LZMA2)</td><td style="text-align:center;">✅</td></tr><tr><td><strong>TAR</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td></tr><tr><td><strong>GZIP (.gz)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>BZIP2 (.bz2)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>XZ</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>Zstandard (.zst)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>RAR</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅ (读取)</td><td style="text-align:center;">✅ (读取)</td></tr></tbody></table><blockquote><p><strong>注意</strong>：由于许可限制，不支持 RAR 压缩。NueZip 可以读取 RAR 归档，包括多卷和加密的 RAR 归档。</p></blockquote><h2 id="格式详情" tabindex="-1">格式详情 <a class="header-anchor" href="#格式详情" aria-label="Permalink to &quot;格式详情&quot;">​</a></h2><h3 id="zip" tabindex="-1">ZIP <a class="header-anchor" href="#zip" aria-label="Permalink to &quot;ZIP&quot;">​</a></h3><ul><li><strong>压缩</strong>：Store、Deflate、Deflate64、BZIP2、LZMA、PPMd</li><li><strong>加密</strong>：AES-256（推荐）、ZipCrypto（旧版）</li><li><strong>卷支持</strong>：多卷拆分归档（<code>.zip.001</code>、<code>.zip.002</code>、...）</li><li><strong>最适合</strong>：跨平台的通用兼容性</li></ul><h3 id="_7-zip" tabindex="-1">7-Zip <a class="header-anchor" href="#_7-zip" aria-label="Permalink to &quot;7-Zip&quot;">​</a></h3><ul><li><strong>压缩</strong>：LZMA2（默认）、LZMA、PPMd、BZIP2、Deflate</li><li><strong>加密</strong>：AES-256</li><li><strong>卷支持</strong>：多卷拆分归档</li><li><strong>最适合</strong>：最大压缩比</li></ul><h3 id="tar" tabindex="-1">TAR <a class="header-anchor" href="#tar" aria-label="Permalink to &quot;TAR&quot;">​</a></h3><ul><li><strong>压缩</strong>：不压缩，或与 GZIP/BZIP2/XZ/Zstandard 组合</li><li><strong>最适合</strong>：Unix/Linux 归档，保留文件权限</li></ul><h3 id="gzip-bzip2-xz-zstandard" tabindex="-1">GZIP / BZIP2 / XZ / Zstandard <a class="header-anchor" href="#gzip-bzip2-xz-zstandard" aria-label="Permalink to &quot;GZIP / BZIP2 / XZ / Zstandard&quot;">​</a></h3><ul><li><strong>独立</strong> 压缩格式（单文件，无归档打包）</li><li>常与 TAR 组合使用（<code>.tar.gz</code>、<code>.tar.xz</code>、<code>.tar.zst</code>）</li></ul><h3 id="rar" tabindex="-1">RAR <a class="header-anchor" href="#rar" aria-label="Permalink to &quot;RAR&quot;">​</a></h3><ul><li><strong>读取支持</strong>：RAR4、RAR5、多卷、加密</li><li><strong>修复</strong>：恢复记录与重建</li><li><strong>写入</strong>：不支持</li></ul><h2 id="提示" tabindex="-1">提示 <a class="header-anchor" href="#提示" aria-label="Permalink to &quot;提示&quot;">​</a></h2><ul><li><strong>与他人共享时</strong>：使用 <strong>ZIP</strong> — 它是兼容性最广泛的格式</li><li><strong>个人归档时</strong>：使用 <strong>7-Zip</strong> — 最佳压缩比，节省磁盘空间</li><li><strong>大型文件</strong>：使用 <strong>拆分 ZIP</strong> 或 <strong>拆分 7-Zip</strong> 拆分为易管理的卷</li><li><strong>敏感数据时</strong>：始终启用 <strong>AES-256 加密</strong> 并设置强密码</li></ul>',18)])])}const u=e(l,[["render",d]]);export{x as __pageData,u as default};
